<Layout title="Books | Bookshelf" section="books">
  <h1>All books</h1>
  <div role="group" aria-label="Filter by tag" id="tag-filter">
    <button type="button" aria-pressed="true" data-tag="">All</button>
    {tags.map((t) => <button type="button" aria-pressed="false" data-tag={t}>{t}</button>)}
  </div>
  <ul aria-label="Books" id="book-list">
    {
      books.map((b) => (
        <li data-slug={b.id} data-tags={JSON.stringify(b.data.tags)}>
          <a href={`/books/${b.id}`}>{b.data.title}</a>
          <span>{b.data.author}, {b.data.year}</span>
          <strong class="favorite" hidden>Favorite</strong>
        </li>
      ))
    }
  </ul>
</Layout>

<script>
  import { getFavorites } from '../../lib/favorites';

  const favorites = getFavorites();
  const items = document.querySelectorAll<HTMLLIElement>('#book-list li');
  items.forEach((li) => {
    const mark = li.querySelector<HTMLElement>('.favorite');
    if (mark) mark.hidden = !favorites.includes(li.dataset.slug ?? '');
  });

  const buttons = document.querySelectorAll<HTMLButtonElement>('#tag-filter button');
  buttons.forEach((btn) => {
    btn.addEventListener('click', () => {
      const tag = btn.dataset.tag ?? '';
      buttons.forEach((b) => b.setAttribute('aria-pressed', String(b === btn)));
      items.forEach((li) => {
        const tags: string[] = JSON.parse(li.dataset.tags ?? '[]');
        li.hidden = tag !== '' && !tags.includes(tag);
      });
    });
  });
</script>
