  import { getFavorites, setFavorites } from '../../lib/favorites';

  const btn = document.querySelector<HTMLButtonElement>('#favorite')!;
  const slug = btn.dataset.slug ?? '';
  const render = () => {
    btn.textContent = getFavorites().includes(slug) ? 'Remove from favorites' : 'Add to favorites';
