cat > src/pages/contact.astro <<'EOF'
---
import Layout from '../layouts/Layout.astro';
import { validateContact, type ContactErrors } from '../lib/validate';

export const prerender = false;

let values = { name: '', email: '', message: '' };
let errors: ContactErrors = {};
let success = '';

if (Astro.request.method === 'POST') {
  let form: FormData | undefined;
  try {
    form = await Astro.request.formData();
  } catch {
    form = undefined;
  }
  const get = (k: string) => String(form?.get(k) ?? '').trim();
  const sent = { name: get('name'), email: get('email'), message: get('message') };
  errors = validateContact(sent);
  if (Object.keys(errors).length > 0) values = sent;
  else success = `Thanks, ${sent.name}! Your message has been sent.`;
}
---

<Layout title="Contact | Bookshelf" section="contact">
  <h1>Contact</h1>
  <p id="success" role="status">{success}</p>
  <form method="post" action="/contact" novalidate id="contact-form">
    <div>
      <label for="name">Name</label>
      <input type="text" id="name" name="name" value={values.name} />
      <span class="error" data-error="name">{errors.name}</span>
    </div>
    <div>
      <label for="email">Email</label>
      <input type="email" id="email" name="email" value={values.email} />
      <span class="error" data-error="email">{errors.email}</span>
    </div>
    <div>
      <label for="message">Message</label>
      <textarea id="message" name="message">{values.message}</textarea>
      <span class="error" data-error="message">{errors.message}</span>
    </div>
    <button type="submit">Send</button>
  </form>
</Layout>

<script>
  import { validateContact } from '../lib/validate';

  const form = document.querySelector<HTMLFormElement>('#contact-form')!;
  const success = document.querySelector<HTMLElement>('#success')!;

  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const field = (n: string) => form.elements.namedItem(n) as HTMLInputElement | HTMLTextAreaElement;
    const values = {
      name: field('name').value.trim(),
      email: field('email').value.trim(),
      message: field('message').value.trim(),
    };
    const errors = validateContact(values);
    for (const key of ['name', 'email', 'message'] as const) {
      form.querySelector<HTMLElement>(`[data-error="${key}"]`)!.textContent = errors[key] ?? '';
    }
    if (Object.keys(errors).length > 0) {
      success.textContent = '';
      return;
    }
    try {
      const res = await fetch(form.action, { method: 'POST', body: new URLSearchParams(values) });
      if (!res.ok) throw new Error(String(res.status));
    } catch {
      success.textContent = 'Something went wrong. Please try again.';
      return;
    }
    success.textContent = `Thanks, ${values.name}! Your message has been sent.`;
    form.reset();
  });
</script>
EOF
